const publicTrickYears = `-- name: PublicTrickYears :many
SELECT DISTINCT year FROM tricks WHERE deleted_at IS NULL ORDER BY year DESC
`

func (q *Queries) PublicTrickYears(ctx context.Context) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, publicTrickYears)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var year int64
		if err := rows.Scan(&year); err != nil {
			return nil, err
		}
		items = append(items, year)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
